<script setup lang="ts">
import { pluginI18n, displayLocale } from '../i18n.ts'
const { t: i18nT } = pluginI18n('builtin.taskManager')

import { vResizableColumns } from '../table-columns'
import { computed, ref, watch } from 'vue'
import type { TaskManagerGpu, TaskManagerHistoryPoint } from '@webnav/shared'
import { formatMemory, formatPercent, formatRate, gpuSource, performanceReason, usageHeat } from '../task-manager'
const props = defineProps<{ point: TaskManagerHistoryPoint }>()
const cpuPage = ref(0), open = ref(false), pageSize = 64
const performance = computed(() => props.point.performance)
const cpuPages = computed(() => Math.max(1, Math.ceil((performance.value?.cpuLogical.length ?? 0) / pageSize)))
const cores = computed(() => performance.value?.cpuLogical.slice(cpuPage.value * pageSize, (cpuPage.value + 1) * pageSize) ?? [])
function bytes(value?: number | null) { return value == null ? i18nT('m460b3574e4bd') : formatMemory(value) }
function sampledAt(value?: number) { return new Date(value ?? performance.value?.sampledAt ?? props.point.sampledAt).toLocaleString(displayLocale()) }
function gpuName(gpu: TaskManagerGpu) { return (performance.value?.gpus.filter(item => item.name === gpu.name).length ?? 0) > 1 ? `${gpu.name} · ${gpu.id}` : gpu.name }
function shared(gpu: TaskManagerGpu) { return gpu.sharedMemoryUsedBytes !== undefined || gpu.sharedMemoryTotalBytes !== undefined }
watch(() => props.point.id, () => { cpuPage.value = 0; open.value = false })
</script>
<template>
  <details class="tm-history-hardware" :open="open" @toggle="open = ($event.target as HTMLDetailsElement).open">
    <summary>{{ i18nT('me29c594f6670') }}<span>{{ i18nT('m5e2c65b33c63') }}</span></summary>
    <div v-if="open" class="tm-hardware-content">
      <p v-if="!performance" class="tm-hardware-empty">{{ i18nT('m442af3c7da3c') }}</p>
      <template v-else>
        <p class="tm-hardware-note">{{ i18nT('m859f66e241e6', { p0: (sampledAt(point.sampledAt)) }) }}</p>
        <section :aria-label="i18nT('m9262dfe85bc1')"><header><h4>{{ i18nT('me6f3fc975d0d') }}<small>{{ i18nT('m4f86cfd6e0f2', { p0: (performance.cpuLogical.length) }) }}</small></h4><div class="tm-hardware-pages"><button class="icon-button" :disabled="cpuPage === 0" :aria-label="i18nT('m3cb77e1630a1')" @click="cpuPage--">‹</button><span>{{ cpuPage + 1 }} / {{ cpuPages }}</span><button class="icon-button" :disabled="cpuPage + 1 >= cpuPages" :aria-label="i18nT('m0ded628f97cb')" @click="cpuPage++">›</button></div></header><div v-if="cores.length" class="tm-history-core-grid"><div v-for="core in cores" :key="core.id" class="tm-history-core" :class="'heat-' + usageHeat(core.usagePercent)"><span>CPU {{ core.id }}</span><strong>{{ formatPercent(core.usagePercent) }}</strong></div></div><p v-else class="tm-hardware-empty">{{ i18nT('mde9077026cc2') }}</p><p class="tm-hardware-note">{{ i18nT('m7bc35cb42cad') }}</p></section>
        <section :aria-label="i18nT('mab8b5195482f')"><header><h4>{{ i18nT('mde7b72a3f852') }}<small>{{ i18nT('m0f3606bbd947', { p0: (performance.disks.length) }) }}</small></h4></header><div v-if="performance.disks.length" class="tm-hardware-table-scroll"><table v-resizable-columns="{ id: 'task-manager.history-disks', widths: [190, 120, 120, 100, 130, 180], fill: 0 }"><thead><tr><th>{{ i18nT('me1506406a5bd') }}</th><th>{{ i18nT('m534cb3fa8fbf') }}</th><th>{{ i18nT('m5c783c467965') }}</th><th>{{ i18nT('mcaaf682ff0b1') }}</th><th>{{ i18nT('m39fdf63d0368') }}</th><th>{{ i18nT('md7681e13941e') }}</th></tr></thead><tbody><tr v-for="disk in performance.disks" :key="disk.id"><td :title="disk.id">{{ disk.name }}</td><td>{{ formatRate(disk.readBytesPerSecond) }}</td><td>{{ formatRate(disk.writeBytesPerSecond) }}</td><td :class="'heat-' + usageHeat(disk.activePercent)">{{ formatPercent(disk.activePercent) }}</td><td>{{ bytes(disk.totalBytes) }}</td><td>{{ sampledAt(disk.sampledAt) }}</td></tr></tbody></table></div><p v-else class="tm-hardware-empty">{{ i18nT('me83d45e8b078') }}</p></section>
        <section :aria-label="i18nT('ma32255ac8955')"><header><h4>{{ i18nT('m5192ce948bbe') }}<small>{{ i18nT('m8eaa29c22a00', { p0: (performance.gpus.length) }) }}</small></h4></header><div v-if="performance.gpus.length" class="tm-history-gpus"><article v-for="gpu in performance.gpus" :key="gpu.id" class="tm-history-gpu"><h5 :title="gpu.id">{{ gpuName(gpu) }}</h5><p v-if="gpu.utilizationScope === 'visible-clients'" class="tm-hardware-scope">{{ i18nT('md789d8390716') }}</p><dl><div><dt>{{ i18nT('m194825842f5a') }}</dt><dd :class="'heat-' + usageHeat(gpu.utilizationPercent)">{{ formatPercent(gpu.utilizationPercent) }}</dd></div><div><dt>{{ i18nT('m356358d9a9ce') }}</dt><dd>{{ bytes(gpu.memoryUsedBytes) }} / {{ bytes(gpu.memoryTotalBytes) }}</dd></div><div v-if="shared(gpu)"><dt>{{ i18nT('m8fe9666af266') }}</dt><dd>{{ bytes(gpu.sharedMemoryUsedBytes) }} / {{ bytes(gpu.sharedMemoryTotalBytes) }}</dd></div><div><dt>{{ i18nT('m3732e264dfa9') }}</dt><dd>{{ gpu.temperatureCelsius == null ? i18nT('m460b3574e4bd') : gpu.temperatureCelsius.toFixed(0) + ' °C' }}</dd></div></dl><p class="tm-hardware-note">{{ i18nT('m50cbd0db7cf5', { p0: (gpuSource(gpu.source)), p1: (sampledAt(gpu.sampledAt)) }) }}</p></article></div><p v-else class="tm-hardware-empty">{{ i18nT('m3e1244907271') }}</p><p v-if="performance.gpus.length" class="tm-hardware-note">{{ i18nT('mb6dc11064f0f') }}</p></section>
        <details v-if="performance.unavailable.length" class="tm-hardware-unavailable"><summary>{{ i18nT('me0165c6ff8e4', { p0: (performance.unavailable.length) }) }}</summary><ul><li v-for="reason in performance.unavailable" :key="reason">{{ performanceReason(reason) }}</li></ul></details>
      </template>
    </div>
  </details>
</template>
